def process_playlist_items(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        data = json.load(f)
    # The structure: {"type":"text","text":"{\\n  \"items\": [ ... ]}"}
    # Need to parse the inner JSON string
    inner_text = data.get('text', '')
    try:
        inner_data = json.loads(inner_text)
    except json.JSONDecodeError:
        # maybe it's already parsed?
        inner_data = data
    items = inner_data.get('items', [])
    videos = []
    for item in items:
        playlist_item = item.get('playlistItem', {})
        video_details = item.get('videoDetails', {})
        video_id = video_details.get('id')
        if not video_id:
            continue
        title = video_details.get('snippet', {}).get('title', '')
        published_at = video_details.get('snippet', {}).get('publishedAt', '')
        duration_str = video_details.get('contentDetails', {}).get('duration', 'PT0S')
        description = video_details.get('snippet', {}).get('description', '')
        # parse date
        try:
            pub_date = datetime.datetime.fromisoformat(published_at.replace('Z', '+00:00'))
        except Exception as e:
            print(f"Error parsing date {published_at}: {e}")
            continue
        # filter by date range: 2024-01-01 to 2025-07-01 (inclusive)
        start_date = datetime.datetime(2024, 1, 1, tzinfo=datetime.timezone.utc)
        end_date = datetime.datetime(2025, 7, 1, tzinfo=datetime.timezone.utc)
        if pub_date < start_date or pub_date > end_date:
            continue
        # filter duration > 2 minutes (120 seconds)
        duration_seconds = parse_duration(duration_str)
        if duration_seconds < 120:
            continue
        # categorize
        category = categorize_video(title, description)
        # weekday (0=Monday, 6=Sunday) ISO weekday: Monday=1, Sunday=7
        weekday = pub_date.isoweekday()  # 1=Monday, 7=Sunday
        weekday_name = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][weekday-1]
        videos.append({
            'video_id': video_id,
            'title': title,
            'category': category,
            'published_at': published_at,
            'duration_seconds': duration_seconds,
            'duration_formatted': format_duration(duration_seconds),
            'weekday': weekday_name,
            'pub_date': pub_date
        })
    # sort by published_at ascending
    videos.sort(key=lambda x: x['pub_date'])
    return videos

def compute_statistics(videos):
    if not videos:
        return {}
    # Most common publish weekday
    weekday_counts = defaultdict(int)
    for v in videos:
        weekday_counts[v['weekday']] += 1
    most_common = max(weekday_counts.items(), key=lambda x: x[1])[0]
    # Average duration in seconds
    avg_duration_seconds = sum(v['duration_seconds'] for v in videos) / len(videos)
    avg_duration_formatted = format_duration(int(avg_duration_seconds))
    # Average publish interval (days between consecutive uploads)
    dates = [v['pub_date'] for v in videos]
    dates.sort()
    intervals = []
    for i in range(1, len(dates)):
        delta = dates[i] - dates[i-1]
        intervals.append(delta.days)
    avg_interval = sum(intervals) / len(intervals) if intervals else 0
    # Weekday proportions
    total = len(videos)
    proportions = {}
    for day in ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']:
        proportions[day] = weekday_counts.get(day, 0) / total
    return {
        'most_common_weekday': most_common,
        'avg_duration_seconds': avg_duration_seconds,
        'avg_duration_formatted': avg_duration_formatted,
        'avg_interval_days': avg_interval,
        'weekday_proportions': proportions
    }

