ing day if date is not trading)\n    # We'll locate the index position\n    if date not in price_df.index:\n        # find the next trading day after date\n        future_dates = price_df.index[price_df.index >= date]\n        if len(future_dates) == 0:\n            return None, None  # no data after rating date\n        date = future_dates[0]\n    start_idx = price_df.index.get_loc(date)\n    end_idx = start_idx + horizon_days\n    if end_idx >= len(price_df):\n        return None, None  # insufficient forward data\n    start_price = price_df.iloc[start_idx]['Close']\n    end_price = price_df.iloc[end_idx]['Close']\n    ret = (end_price - start_price) / start_price * 100\n    return ret, date\n\n# Horizon days (approx trading days)\nhorizons = {'4m': 84, '5m': 105, '6m': 126}\n\ndef evaluate_ratings(rec_df, stock_hist, bench_hist, horizons):\n    results = {}\n    for horizon_name, days in horizons.items():\n        signals = 0\n        excluded = 0\n        hits = 0\n        excess_returns = []\n        for _, row in rec_df.iterrows():\n            rating_date = row['GradeDate']\n            direction = row['Direction']\n            # Compute stock return\n            stock_ret, actual_date = compute_forward_returns(stock_hist, rating_date, days)\n            if stock_ret is None:\n                excluded += 1\n                continue\n            # Compute benchmark return\n            bench_ret, _ = compute_forward_returns(bench_hist, rating_date, days)\n            if bench_ret is None:\n                excluded += 1\n                continue\n            signals += 1\n            excess = stock_ret - bench_ret\n            excess_returns.append(excess)\n            # Determine actual direction\n            if stock_ret > 2:  # Up (greater than +2%)\n                actual = 'Up'\n            elif stock_ret < -2:  # Down (less than -2%)\n                actual = 'Down'\n            else:\n                actual = 'Flat'\n            # Check hit\n            if direction == 'Flat':\n                hit = (actual == 'Flat')  # Flat prediction hit if actual within ±2%\n            else:\n                hit = (direction == actual)\n            if hit:\n                hits += 1\n        hit_rate = (hits / signals * 100) if signals > 0 else 0\n        avg_excess = np.mean(excess_returns) if excess_returns else 0\n        results[horizon_name] = {\n            'HitRate': hit_rate,\n            'AvgExcess': avg_excess,\n            'Signals': signals,\n            'Excluded': excluded\n        }\n    return results\n\nprint(\"Evaluating NVDA...\")\nnvda_results = evaluate_ratings(nvda_rec, nvda_hist, sp500_hist, horizons)\nprint(\"Evaluating AAPL...\")\naapl_results = evaluate_ratings(aapl_rec, aapl_hist, sp500_hist, horizons)\n\nprint(\"\\nNVDA Results:\")\nfor h, r in nvda_results.items():\n    print(f\"  {h}: Hit Rate {r['HitRate']:.2f}%, Avg Excess {r['AvgExcess']:.2f}%, Signals {r['Signals']}, Excluded {r['Excluded']}\")\n\nprint(\"\\nAAPL Results:\")\nfor h, r in aapl_results.items():\n    print(f\"  {h}: Hit Rate {r['HitRate']:.2f}%, Avg Excess {r['AvgExcess']:.2f}%, Signals {r['Signals']}, Excluded {r['Excluded']}\")\n\n# Save results to a file\nwith open('/workspace/dumps/workspace/analysis/results.txt', 'w') as f:\n    f.write(\"NVDA Results:\\n\")\n    for h, r in nvda_results.items():\n        f.write(f\"{h}: {r}\\n\")\n    f.write(\"\\nAAPL Results:\\n\")\n    for h, r in aapl_results.items():\n        f.write(f\"{h}: {r}\\n\")", "path": "/workspace/dumps/workspace/analysis/analyze.py"}
